#include <iostream>
#include <string>
using namespace std;

int main() {
    string a = "apple";
    string b = "banana";
    string c = "Zebra";
    string d = "app";

    cout << boolalpha;
    cout << (a < b) << endl;      // a comes before b
    cout << (c < a) << endl;      // capitals come before small letters
    cout << (d < a) << endl;      // a shorter start comes first
    return 0;
}

